# Rebuilt 2026-09-14 against tuned225 matrix; source: /home/gaga/huzhan/MSI_ALL_aligned_11samples_consensus0.1Da/spatial_metabolite_modules_10samples/5A_step5_posthoc_domain_relation.R
# 5A Step 5: post-hoc relation of frozen modules to old domains
local({
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(pheatmap)})
BASE<-'/home/gaga/huzhan/MSI_ALL_aligned_10samples_consensus_tuned225';OUT<-file.path(BASE,'spatial_metabolite_modules_10samples_tuned225');S5<-file.path(OUT,'step5_posthoc_domain_relation');dir.create(S5,recursive=TRUE,showWarnings=FALSE)
sa<-readRDS(file.path(OUT,'step4_module_activity_spatial_organization','pixel_module_activity_scores.rds'));meta<-as.data.table(sa$pixel_metadata);scores<-sa$scores;modules<-colnames(scores);mod<-readRDS(file.path(OUT,'step3_modules','MSI_consensus_modules.rds'));reps<-as.data.table(mod$representatives)[module!='grey'];q<-fread(file.path(BASE,'cross_sample_common_domains_10samples_1B_tuned225','cross_sample_feature_qc_physical_sample_level.csv'));valfi<-reps[!feature_index%in%q[selected_for_common_domain_model==TRUE,matrix_feature_index],feature_index]
# Independent bridge score excludes every feature used to construct the 1B common-domain model.
Xall<-readRDS(file.path(BASE,'pixel_by_feature_matrix_aligned_logCPM.rds'));X<-as.matrix(Xall[meta$original_pixel_row,valfi,drop=FALSE]);rm(Xall);a0<-readRDS(file.path(BASE,'intratumor_spatial_heterogeneity_10samples_part1_consensus_tuned225','tumor_pixels_within_sample_consensus_domains.rds'));tech<-as.data.table(a0)[order(original_pixel_row),.(original_pixel_row,raw_tic,detected_peak_count,alignment_nmatch)];rm(a0);stopifnot(all(tech$original_pixel_row==meta$original_pixel_row));safez<-function(v){s<-sd(v,na.rm=TRUE);if(!is.finite(s)||s<1e-10)return(rep(0,length(v)));as.numeric(scale(v))};valscores<-matrix(NA_real_,nrow(meta),length(modules),dimnames=list(NULL,modules));valsupport<-list()
for(s in sort(unique(meta$sample_id))){ii<-which(meta$sample_id==s);Y<-X[ii,,drop=FALSE];D<-cbind(1,safez(log1p(tech$raw_tic[ii])),safez(tech$detected_peak_count[ii]),safez(tech$alignment_nmatch[ii]));Z<-apply(qr.resid(qr(D),Y),2,safez);for(mm in modules){f0<-reps[module==mm&feature_index%in%valfi,feature_index];jj<-match(f0,valfi);if(length(jj)>=3)valscores[ii,mm]<-rowMeans(Z[,jj,drop=FALSE]);valsupport[[length(valsupport)+1L]]<-data.table(sample=s,module=mm,n_validation_features=length(jj))}};rm(X);gc();saveRDS(list(scores=valscores,feature_definition='representative module features excluding all 500 selected_for_common_domain_model features',support=rbindlist(valsupport)),file.path(S5,'validation_only_module_scores_for_common_domain_bridge.rds'));fwrite(rbindlist(valsupport),file.path(S5,'validation_only_feature_support.csv'))
a<-as.data.table(readRDS(file.path(BASE,'intratumor_spatial_heterogeneity_10samples_part1_consensus_tuned225','tumor_pixels_within_sample_consensus_domains.rds')))[,.(original_pixel_row,within_domain=as.character(consensus_domain),within_stable=stable_core_pixel)];b<-as.data.table(readRDS(file.path(BASE,'cross_sample_common_domains_10samples_1B_tuned225','tumor_pixels_with_common_meta_domains.rds')))[,.(original_pixel_row,common_domain=as.character(common_meta_domain),common_stable=stable_core_pixel)];lab<-merge(meta,a,by='original_pixel_row');lab<-merge(lab,b,by='original_pixel_row');ord<-match(meta$original_pixel_row,lab$original_pixel_row);lab<-lab[ord];stopifnot(all(lab$original_pixel_row==meta$original_pixel_row))
eta2<-function(v,g,keep=rep(TRUE,length(v))){ok<-keep&is.finite(v)&!is.na(g);v<-v[ok];g<-g[ok];if(length(v)<10||uniqueN(g)<2)return(NA_real_);tot<-sum((v-mean(v))^2);if(tot<=0)return(NA_real_);1-sum(vapply(split(v,g),function(x)sum((x-mean(x))^2),numeric(1)))/tot}
res<-list();for(s in sort(unique(lab$sample_id))){ii<-which(lab$sample_id==s);for(mm in modules){res[[length(res)+1L]]<-data.table(sample=s,module=mm,within_eta2_all=eta2(scores[ii,mm],lab$within_domain[ii]),within_eta2_stable=eta2(scores[ii,mm],lab$within_domain[ii],lab$within_stable[ii]),common_eta2_all=eta2(scores[ii,mm],lab$common_domain[ii]),common_eta2_stable=eta2(scores[ii,mm],lab$common_domain[ii],lab$common_stable[ii]),common_eta2_validation_only=eta2(valscores[ii,mm],lab$common_domain[ii]),common_eta2_validation_only_stable=eta2(valscores[ii,mm],lab$common_domain[ii],lab$common_stable[ii]))}};res<-rbindlist(res);fwrite(res,file.path(S5,'module_domain_eta2_by_sample.csv'))
# Common-domain mean activities are sample-standardized, then summarized across physical samples.
prof<-rbindlist(lapply(sort(unique(lab$sample_id)),function(s){ii<-which(lab$sample_id==s);rbindlist(lapply(modules,function(mm)data.table(sample=s,module=mm,common_domain=lab$common_domain[ii],score=scores[ii,mm],validation_score=valscores[ii,mm])))[,.(mean_score=mean(score),mean_validation_score=mean(validation_score,na.rm=TRUE),n_pixels=.N),by=.(sample,module,common_domain)]}));fwrite(prof,file.path(S5,'common_domain_module_profiles_by_sample.csv'));profmed<-prof[,.(median_score=median(mean_score),positive_samples=sum(mean_score>0),median_validation_score=median(mean_validation_score,na.rm=TRUE),validation_positive_samples=sum(mean_validation_score>0,na.rm=TRUE),evaluable_validation_samples=sum(is.finite(mean_validation_score))),by=.(module,common_domain)];fwrite(profmed,file.path(S5,'common_domain_module_profiles_cross_sample_median.csv'))
sumr<-res[,.(median_within_eta2=median(within_eta2_all,na.rm=TRUE),median_common_eta2=median(common_eta2_all,na.rm=TRUE),median_common_eta2_validation_only=median(common_eta2_validation_only,na.rm=TRUE),n_validation_evaluable=sum(is.finite(common_eta2_validation_only))),by=module];setorder(sumr,-median_common_eta2_validation_only);fwrite(sumr,file.path(S5,'module_domain_relation_summary.csv'))
pdf(file.path(S5,'step5_posthoc_domain_relation.pdf'),width=10,height=8);p1<-ggplot(res[is.finite(common_eta2_validation_only)],aes(x=reorder(module,common_eta2_validation_only,FUN=median),y=common_eta2_validation_only))+geom_boxplot(fill='#FDB462',outlier.size=.7)+coord_flip()+labs(x=NULL,y='Eta-squared',title='Common-domain association using validation-only module scores')+theme_bw(base_size=11);print(p1);mw<-dcast(res,sample~module,value.var='within_eta2_all');pheatmap(replace(as.matrix(mw[,-1]),!is.finite(as.matrix(mw[,-1])),0),labels_row=mw$sample,main='Within-sample domain eta-squared (descriptive)',border_color=NA);mc<-dcast(res,sample~module,value.var='common_eta2_validation_only');pheatmap(replace(as.matrix(mc[,-1]),!is.finite(as.matrix(mc[,-1])),0),labels_row=mc$sample,main='Common-domain eta-squared (validation-only bridge)',border_color=NA);dev.off()
writeLines(c('This is a post-hoc bridge: module membership was frozen before any domain label was read.','Within-sample domain relations are descriptive because domain discovery and module discovery use overlapping MSI information.','For the common-domain bridge, an additional score excludes all 500 features used by the 1B common-domain model; modules with fewer than 3 remaining features are not evaluated.','No domain result changes module membership, ranking, ion-family collapse, or spatial metrics.','LC-MS/MS is not read.'),file.path(S5,'README.txt'))
cat('STEP5_COMPLETE validation_features',length(valfi),'\n');print(sumr);cat('OUT=',S5,'\n')
})
